package com.mfix.pos;

import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.webkit.WebView;

/** Adds product editing and stock-history access without replacing the existing inventory UI. */
public class InventoryManagementPatchActivity extends PrinterManagementPatchActivity {
    private static final String PATCH =
        "(function(){if(window.__mfixInventoryManagement)return;window.__mfixInventoryManagement=true;"+
        "function esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c];});}"+
        "function persist(){try{if(typeof saveKey==='function'){saveKey('products',STATE.products);saveKey('misc',{returns:STATE.returns,shifts:STATE.shifts,giftCards:STATE.giftCards,preorders:STATE.preorders,auditLog:STATE.auditLog,inventoryHistory:STATE.inventoryHistory});} }catch(e){console.error(e);}}"+
        "function panel(){var v=document.getElementById('view-inventory');if(!v)return;var box=document.getElementById('mfixInventoryTools');if(!box){box=document.createElement('div');box.id='mfixInventoryTools';box.className='card';box.style.marginBottom='12px';v.insertBefore(box,v.firstChild);}var ps=Array.isArray(STATE.products)?STATE.products:[];box.innerHTML='<div class=\"section-title\">📦 ניהול מוצרים</div><div style=\"font-size:12px;color:var(--gray-500);margin-bottom:10px\">עריכת מחיר, עלות, מלאי ו־IMEI/סידורי.</div><div style=\"display:flex;gap:8px;flex-wrap:wrap\"><input id=\"mfixInvSearch\" class=\"input\" style=\"max-width:300px\" placeholder=\"חיפוש מוצר / ברקוד\"><button id=\"mfixInvHistory\" class=\"btn btn-ghost\">📋 היסטוריית מלאי</button></div><div id=\"mfixInvRows\" style=\"margin-top:10px\"></div>';function draw(q){q=String(q||'').toLowerCase();var rows=ps.filter(function(p){return !q||[p.name,p.sku,p.barcode,p.imei,p.serial].some(function(x){return String(x||'').toLowerCase().indexOf(q)>=0;});}).slice(0,60);document.getElementById('mfixInvRows').innerHTML=rows.length?'<table class=\"tbl\"><thead><tr><th>מוצר</th><th>מחיר</th><th>מלאי</th><th></th></tr></thead><tbody>'+rows.map(function(p){return '<tr><td>'+esc(p.name||'ללא שם')+'</td><td>₪'+Number(p.price||0).toFixed(2)+'</td><td>'+Number(p.stock||0)+'</td><td><button class=\"btn btn-outline\" data-mfix-edit=\"'+esc(p.id)+'\">✏️ ערוך</button></td></tr>';}).join('')+'</tbody></table>':'<div class=\"empty-state\">אין מוצרים</div>';document.querySelectorAll('[data-mfix-edit]').forEach(function(b){b.onclick=function(){var p=ps.find(function(x){return String(x.id)===String(b.getAttribute('data-mfix-edit'));});if(!p)return;openModal('<div class=\"modal\"><div class=\"modal-head\"><h3>עריכת מוצר</h3><button class=\"modal-close\" onclick=\"closeModal()\">×</button></div><div class=\"modal-body\"><div class=\"field\"><label class=\"flabel\">שם</label><input id=\"mfixPN\" class=\"input\" value=\"'+esc(p.name||'')+'\"></div><div class=\"grid2\"><div class=\"field\"><label class=\"flabel\">מחיר</label><input id=\"mfixPP\" class=\"input\" type=\"number\" step=\"0.01\" value=\"'+Number(p.price||0)+'\"></div><div class=\"field\"><label class=\"flabel\">עלות</label><input id=\"mfixPC\" class=\"input\" type=\"number\" step=\"0.01\" value=\"'+Number(p.cost||0)+'\"></div></div><div class=\"field\"><label class=\"flabel\">מלאי</label><input id=\"mfixPS\" class=\"input\" type=\"number\" value=\"'+Number(p.stock||0)+'\"></div><div class=\"field\"><label class=\"flabel\">IMEI / סידורי</label><input id=\"mfixPI\" class=\"input\" value=\"'+esc(p.imei||p.serial||'')+'\"></div></div><div class=\"modal-foot\"><button class=\"btn btn-ghost\" onclick=\"closeModal()\">ביטול</button><button id=\"mfixPSave\" class=\"btn btn-primary\">שמור</button></div></div>');document.getElementById('mfixPSave').onclick=function(){var before=Number(p.stock||0),after=Number(document.getElementById('mfixPS').value||0);p.name=document.getElementById('mfixPN').value.trim();p.price=Number(document.getElementById('mfixPP').value||0);p.cost=Number(document.getElementById('mfixPC').value||0);p.stock=after;p.imei=document.getElementById('mfixPI').value.trim();p.serial=p.imei;if(!Array.isArray(STATE.inventoryHistory))STATE.inventoryHistory=[];if(before!==after)STATE.inventoryHistory.unshift({id:'invh_'+Date.now(),productId:p.id,type:after>before?'adjust_in':'adjust_out',qty:Math.abs(after-before),before:before,after:after,reason:'עריכה ידנית',at:new Date().toISOString()});persist();closeModal();toast('המוצר נשמר','ok');draw(document.getElementById('mfixInvSearch').value);};};});}document.getElementById('mfixInvSearch').oninput=function(){draw(this.value);};document.getElementById('mfixInvHistory').onclick=function(){var hs=Array.isArray(STATE.inventoryHistory)?STATE.inventoryHistory:[];openModal('<div class=\"modal wide\"><div class=\"modal-head\"><h3>היסטוריית מלאי</h3><button class=\"modal-close\" onclick=\"closeModal()\">×</button></div><div class=\"modal-body\">'+(hs.length?'<table class=\"tbl\"><thead><tr><th>תאריך</th><th>מוצר</th><th>לפני</th><th>אחרי</th><th>סיבה</th></tr></thead><tbody>'+hs.slice(0,200).map(function(x){var p=ps.find(function(z){return String(z.id)===String(x.productId);});return '<tr><td>'+esc(x.at||'')+'</td><td>'+esc(p?p.name:x.productId)+'</td><td>'+x.before+'</td><td>'+x.after+'</td><td>'+esc(x.reason||'')+'</td></tr>';}).join('')+'</tbody></table>':'<div class=\"empty-state\">אין היסטוריית מלאי</div>')+'</div></div>');};draw('');}panel();setInterval(panel,2000);console.log('[MFIX] inventory management patch active');})();";

    @Override protected void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState);
        View root=((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);
        if(root instanceof WebView)((WebView)root).postDelayed(()->((WebView)root).evaluateJavascript(PATCH,null),4200);
    }
}
